(function(root){
'use strict';
const M=root.CampaignModel,esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let H,assets,error='',loading,searchMode=0,searchTerms=['',''],bagTab=0,bagQuery='',cardView,addView,mapView;
const state=()=>H.state(),owner=()=>H.page()==='personalInventory'?H.active()?.id:null;
const button=(action,label,data='',cls='')=>`<button type="button" class="btn ${cls}" data-camp="${action}" ${data}>${label}</button>`;
const tabs=(labels,index,kind)=>`<div class="camp-tabs" role="tablist">${labels.map((t,i)=>button('tab',esc(t),`data-kind="${kind}" data-index="${i}" role="tab" aria-selected="${index===i}"`,index===i?'selected':'')).join('')}</div>`;
const heading=(title,right='')=>`<div class="camp-heading"><h1>${esc(title)}</h1>${right}</div>`;
function load(){if(loading)return loading;loading=Promise.all(['card-database','team-inventory-catalog','portraits','rule-names','rule-icons'].map(n=>fetch(`catalog/${n}.json`).then(r=>{if(!r.ok)throw Error('资料暂时无法加载，请联网后重试');return r.json();}))).then(([cards,meta,portraits,names,icons])=>{assets={cards:cards.cards,meta:meta.cards,portraits:portraits.portraitsBySource||{},names,icons};if(H)H.render();}).catch(e=>{error=e.message;if(H)H.render();});return loading;}
function byKey(key){return assets?.cards.find(c=>c.key===key);}
function byReference(id){return M.exact(assets?.cards||[],id);}
function cardOf(entry){return byKey(entry.cardKey)||byReference(entry.reference)[0];}
function tokenize(text){return esc(text).replace(/\{([\w-]+)\}/g,(_,key)=>assets.icons[key]?`<img class="camp-rule-icon" src="${esc(assets.icons[key])}" alt="${esc(assets.names[key]||key)}" title="${esc(assets.names[key]||key)}">`:`<span class="camp-rule">${esc(assets.names[key]||key)}</span>`).replace(/(?:事件|人物|互动|键钥)-\d+[A-E]?/g,s=>button('reference',s,`data-reference="${esc(s)}"`,'camp-inline'));}
function shell(page){
 if(!assets)return heading(page==='map'?'地图':page.includes('Inventory')?'个人背包':page==='inventory'?'团队背包':'检索')+`<section class="panel"><p>${esc(error||'正在加载卡牌资料…')}</p>${error?button('retry','重试'):''}</section>`;
 if(page==='inventory'||page==='personalInventory')return inventoryPage();if(page==='search')return searchPage();if(page==='map')return mapPage();return '';
}
function inventoryPage(){
 const own=owner(),entries=M.held(state(),own),count=new Set(entries.flatMap(M.keywords)).size;
 const right=own?button('go','返回角色卡','data-page="characters"'):button('fishing','垂钓日志','','small');
 return `<section class="camp-inventory">${heading(own?'个人背包':'团队背包',right)}<div class="camp-summary"><span>${own?esc(H.active().name)+' · ':''}${entries.length}张卡牌 · ${count}个关键词</span>${button('history','已移出','','small')}</div>${own?'':`<div class="camp-coins"><b>梓昆币</b><strong>${M.coins(state()).length}枚</strong></div>`}${tabs(own?['关键词','持有卡牌']:['关键词','持有卡牌','梓昆币'],bagTab,'bag')}<input id="camp-bag-query" type="search" value="${esc(bagQuery)}" placeholder="查找已持有的关键词、名称或卡号" aria-label="搜索背包"><div id="camp-bag-items">${inventoryItems()}</div><div class="camp-add-dock">${button('add','添加','','primary')}</div></section>`;
}
function row(title,subtitle,entry,action='owned',compact=true,key=''){
 const lines=subtitle.replace(/ · ([A-E])(?= · |$)/g,'$1').split(' · ');return `<div class="camp-entry ${compact?'compact':''}" ${entry?`data-manage="${esc(entry.id)}" title="长按或右键管理卡牌"`:''}><button type="button" class="camp-entry-open" data-camp="${action}" ${entry?`data-id="${esc(entry.id)}"`:''} ${key?`data-key="${esc(key)}"`:''}><strong>${esc(title)}</strong><span class="camp-source" title="${esc(subtitle)}"><b>${esc(lines.shift()||'')}</b><small>${esc(lines.join(' · '))}</small></span></button></div>`;
}
function inventoryItems(){
 const own=owner(),entries=M.held(state(),own).sort((a,b)=>b.updatedAt-a.updatedAt),q=bagQuery.trim(),match=e=>!q||[e.display,e.title,e.note,...M.keywords(e)].some(v=>String(v).includes(q)||M.identifier(v).includes(M.identifier(q)));
 let html='';if(bagTab===0){const grouped=new Map();for(const e of entries)for(const word of M.keywords(e)){if(!grouped.has(word))grouped.set(word,[]);grouped.get(word).push(e);}
  for(const [word,list]of grouped)if(!q||word.includes(q)||list.some(match)){const one=list.length===1?list[0]:null;html+=row(word,one?one.display+' · '+one.title:`${list.length}张来源 · 点击查看持有来源`,one,one?'owned':'sources',true,word);}
  for(const e of entries.filter(e=>e.graphicKeyword&&match(e)))html+=row('图形触发线索',e.display+' · '+e.title,e,'owned',true);
 }else if(bagTab===1){for(const e of entries.filter(match))html+=row(e.title||e.display,e.display+' · '+(M.keywords(e).join('、')||'已持有'),e);}
 else for(const n of M.coins(state(),own).filter(n=>!q||String(n).includes(q))){const e=entries.find(e=>e.squillNumber===n);html+=e?row('梓昆币 #'+n,e.display+' · '+e.title,e):row('梓昆币 #'+n,'已记录 · 1枚',null,'coin',true,String(n));}
 return html||'<div class="camp-empty"><h3>这里还没有匹配记录</h3><p>添加手中持有的卡牌后，可在这里集中查看关键词并打开原卡。</p></div>';
}
function searchPage(){return `<section class="camp-search">${heading('检索',button('searchPrefs','防剧透设置','','small'))}${tabs(['冒险索引','卡牌数据库'],searchMode,'search')}<div id="camp-search-results">${searchResults()}</div><div class="camp-search-dock"><small>${state().prefs.databaseText?'文本显示已开启':'防剧透已开启'}</small><input id="camp-search-query" type="search" value="${esc(searchTerms[searchMode])}" placeholder="输入卡号、名称或正文" aria-label="卡号、名称或正文"></div></section>`;}
function searchResults(){
 const query=searchTerms[searchMode].trim();let cards=[];
 if(query)cards=M.searchCards(assets.cards,assets.meta,query).filter(c=>searchMode||!['技能','角色','游荡','法师','游侠','诗人','牧师','战士'].includes(c.category));
 else{const recent=JSON.parse(localStorage.getItem('arydia-web-recent-cards')||'[]');cards=recent.map(byKey).filter(Boolean);}
 const reveal=!!state().prefs.databaseTitles,letter=/^[A-Z]+-\d+[A-E]$/.test(M.identifier(query));if(!reveal&&!letter)cards=cards.filter((c,i,a)=>a.findIndex(x=>x.category===c.category&&x.number===c.number)===i);
 const intro=query?`<p class="muted">${cards.length}条结果</p>`:cards.length?`<div class="camp-summary"><b>最近查阅</b>${button('clearHistory','清空记录','','small')}</div>`:'<div class="panel"><h3>查找卡牌</h3><p>输入编号、名称或正文。查阅过的卡牌会保留在这里。</p></div>';
 return intro+(query&&searchMode&&M.searchHint(query)?`<p class="muted camp-search-hint">${esc(M.searchHint(query))}</p>`:'')+cards.slice(0,150).map(c=>`<button class="camp-result" data-camp="card" data-key="${esc(c.key)}"><b>${esc(reveal||letter?c.display:c.number)}</b><span>${esc(reveal?c.title:'标题已隐藏')}</span></button>`).join('')+(query&&!cards.length?'<p>未找到对应卡牌，请检查编号或搜索词。</p>':'');
}
function showCard(card,owned=false,entryId=null,ownerId=null){if(!card)return H.toast('未找到对应原卡');const recent=JSON.parse(localStorage.getItem('arydia-web-recent-cards')||'[]');localStorage.setItem('arydia-web-recent-cards',JSON.stringify([card.key,...recent.filter(x=>x!==card.key)].slice(0,12)));cardView={card,face:0,owned,entryId,ownerId,named:owned||!!state().prefs.databaseTitles,revealed:new Set()};paintCard();}
function paintCard(){const v=cardView,c=v.card,f=c.faces[v.face],visible=v.owned||state().prefs.databaseText||v.revealed.has(v.face),title=v.named?esc(f.title||c.title):button('cardTitle','显示卡牌标题');const variants=assets.cards.filter(x=>x.category===c.category&&x.number===c.number&&x.state);
 const photo=assets.portraits[f.source],body=visible?`<article class="camp-card-body" data-category="${esc(c.category)}">${photo?`<img class="camp-npc" src="${esc(photo)}" alt="${esc(f.title||c.title)}">`:''}${f.blocks?.length?f.blocks.map(b=>b.text?(b.kind==='heading'?`<h3>${tokenize(b.text)}</h3>`:`<${b.style==='dialogue'?'blockquote':'p'}>${tokenize(b.text).replace(/\n/g,'<br>')}</${b.style==='dialogue'?'blockquote':'p'}>`):'').join(''):`<p>${tokenize(f.workbookText||'请参照实体卡牌。').replace(/\n/g,'<br>')}</p>`}</article>`:`<div class="panel"><p>正文可能包含剧情，请按实体游戏指示查阅。</p>${button('revealCard','展开卡牌正文','','primary')}</div>`;
 const entry=v.entryId?M.bag(state(),v.ownerId).cards.find(e=>e.id===v.entryId&&e.cardKey===c.key):null;
 const memo=entry?`<section class="camp-card-memo" role="region" aria-label="这张卡的备注"><h3>这张卡的备注</h3><textarea id="camp-card-memo" maxlength="20000" rows="2" placeholder="记录用途、线索或待办事项">${esc(v.memoDraft??entry.note)}</textarea><div><small id="camp-memo-status" role="status"></small>${button('saveCardMemo','保存备注','','primary small')}</div></section>`:'';
 H.modal('campaignCard',esc(v.named||visible?c.display:c.number)+(v.entryId?button('sourceSearch','检索','aria-label="转到检索这张卡"','camp-source-jump'):''),`<div class="camp-card-title">${title}</div>${(v.named||visible)&&variants.length>1?`<div class="camp-variants">${variants.map(x=>button('cardVariant',esc(x.state),`data-key="${esc(x.key)}"`,x.key===c.key?'primary':'')).join('')}</div>`:''}${c.faces.length>1?tabs(c.faces.map((f,i)=>f.label||['正面','背面'][i]||'卡面'+(i+1)),v.face,'face'):''}<div id="camp-reading">${body}</div>`,'',memo);
 const reading=document.getElementById('camp-reading');let x=0,y=0;reading?.addEventListener('touchstart',e=>{x=e.touches[0].clientX;y=e.touches[0].clientY;},{passive:true});reading?.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-x,dy=e.changedTouches[0].clientY-y;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.8&&c.faces.length>1){v.face=c.faces.length===2?1-v.face:Math.max(0,Math.min(c.faces.length-1,v.face+(dx<0?1:-1)));paintCard();}},{passive:true});
}
function showAdd(){addView={owner:owner(),mode:0,choices:{}};paintAdd();}
function paintAdd(){const own=addView.owner;H.modal('campaignAdd',own?'添加个人键钥卡':'添加到团队背包',`${own?'<p>记录当前角色的种族剧情键钥卡，按角色分别保存。</p>':tabs(['键钥卡','梓昆币','其它卡牌'],addView.mode,'add')}<textarea id="camp-add-input" rows="3" maxlength="1500" placeholder="${own?'键钥卡号，例如98A、0A':'卡号，例如0A、98A、事件-9；可用逗号批量添加'}"></textarea><div id="camp-add-preview"></div>`,button('saveBag','保存到背包','','primary'));}
function addTokens(){return document.getElementById('camp-add-input').value.split(/[,，、;；\n]+/).map(x=>x.trim()).filter(Boolean);}
function candidates(raw){return M.exact(assets.cards,raw,addView.owner);}
function coinInput(raw){if(addView.owner)return null;const match=(addView.mode===1?/^(?:币|梓昆币|SQL[-#]?)?(\d+)$/i:/^(?:币|梓昆币|SQL[-#]?)(\d+)$/i).exec(raw);return match?Number(match[1]):null;}
function previewAdd(){const out=document.getElementById('camp-add-preview');out.innerHTML=addTokens().slice(0,100).map(raw=>{const n=coinInput(raw);if(n!==null)return `<p>${n>=1&&n<=35?'梓昆币 #'+n:'币编号应为1–35'}</p>`;const found=candidates(raw),chosen=found.length===1?found[0]:found.find(c=>c.key===addView.choices[raw]);if(!chosen)return `<div><p>${esc(raw)}：${found.length?'请选择实体卡当前字母':'未找到卡牌，请核对完整编号和字母'}</p>${found.map(c=>button('chooseAdd',esc(c.display),`data-raw="${esc(raw)}" data-key="${esc(c.key)}"`)).join('')}</div>`;const meta=assets.meta[chosen.key]||{};return `<section class="camp-preview"><b>${esc(chosen.display)} · ${esc(chosen.title)}</b><p>${esc((meta.keywords||[]).join('、')||'保存后可查看原卡并添加备注')}</p>${meta.isSquill&&!meta.squillNumber?`<label>实体卡上的梓昆币编号<input type="number" min="1" max="35" data-manual-coin="${esc(raw)}"></label>`:''}</section>`;}).join('');}
function saveBag(){const raw=addTokens();if(!raw.length||raw.length>100)return H.toast('请填写1–100个编号');const selected=[];try{for(const value of raw){const n=coinInput(value);if(n!==null){if(n<1||n>35)throw Error('币编号应为1–35');selected.push({n});continue;}const found=candidates(value),card=found.length===1?found[0]:found.find(c=>c.key===addView.choices[value]);if(!card)throw Error('请核对并选择 '+value+' 的当前卡面');const manual=[...document.querySelectorAll('[data-manual-coin]')].find(e=>e.dataset.manualCoin===value);selected.push({card,n:manual?Number(manual.value):0});}
 if(H.mutate(s=>{for(const e of selected)if(e.card)M.add(s,e.card,assets.meta,addView.owner,e.n);else M.addCoin(s,e.n);},false)){H.close();H.render();H.toast('已保存到背包');}}catch(e){H.toast(e.message);}}
function manage(id){const own=owner(),entry=M.bag(state(),own).cards.find(e=>e.id===id);if(!entry)return;H.modal('campaignManage',esc(entry.display),`<h3>${esc(entry.title)}</h3><label>关键词，每行一条<textarea id="camp-edit-words" rows="3">${esc(M.keywords(entry).join('\n'))}</textarea></label><label>备注<textarea id="camp-edit-note" rows="3">${esc(entry.note)}</textarea></label><label>卡上标记数量<input id="camp-edit-marks" type="number" min="0" max="999" value="${entry.marks||0}"></label>`,button('archive','移出背包',`data-id="${esc(id)}"`)+button('saveEntry','保存',`data-id="${esc(id)}"`,'primary'));}
function history(){const entries=M.bag(state(),owner()).cards.filter(e=>e.status==='archived').sort((a,b)=>b.updatedAt-a.updatedAt);H.modal('campaignHistory','已移出背包',entries.length?entries.map(e=>`<div class="camp-summary"><span>${esc(e.display)} · ${esc(e.title)}</span>${button('restore','恢复',`data-id="${esc(e.id)}"`,'small')}</div>`).join(''):'<p>还没有移出的记录。</p>');}
function fishing(){const log=M.fishing(state());let checks='';for(let r=0;r<11;r++)for(let c=0;c<3;c++){const n=r+c*11+1;checks+=n<=32?`<label><input type="checkbox" data-fish="fish" value="${n}" ${log.fish.includes(n)?'checked':''}><span>鱼类-${n}</span></label>`:'<span></span>';}
 H.modal('campaignFishing','垂钓日志',`<div class="camp-fish-card"><p class="camp-fish-intro">这本日志是用来记录你关于各类鱼种的发现！每当你捕获一条鱼（或开启一个板块包），就在清单上做个记号。</p><strong id="camp-fish-progress"></strong><div class="camp-fish-grid">${checks}</div><div class="camp-fish-boards">${[1,2,3].map(n=>`<label><input type="checkbox" data-fish="boards" value="${n}" ${log.boards.includes(n)?'checked':''}><span>板块-垂钓${n}</span></label>`).join('')}</div><p class="camp-fish-condition">一旦你标记了清单上的所有方格，抽取：<span>事件-79</span></p></div><div id="camp-fish-complete"></div><label>垂钓备注<textarea id="camp-fish-notes" rows="3" maxlength="10000">${esc(log.notes)}</textarea></label>`);refreshFish();}
function refreshFish(){const log=M.fishing(state());document.getElementById('camp-fish-progress').textContent=`鱼类 ${log.fish.length}/32 · 垂钓板块 ${log.boards.length}/3`;document.getElementById('camp-fish-complete').innerHTML=M.fishingComplete(state())?`<div class="panel"><b>清单已全部完成</b><p>按照实体日志的指示，抽取事件-79。</p>${button('reference','查看事件-79','data-reference="EVT-79"')}</div>`:'';}
let mapAssets,mapLoading,lastDrag=0;
function mapRecord(create=false){if(!state().webMap&&create)state().webMap={version:1,party:null,selected:'E2',explored:[],notes:{},showAll:false};return state().webMap||{version:1,party:null,selected:'E2',explored:[],notes:{},showAll:false};}
function loadMap(){if(mapLoading)return;mapLoading=Promise.all(['geometry','locations','tiles'].map(n=>fetch(`maps/${n}.json`).then(r=>{if(!r.ok)throw Error('地图资料暂未加载，请联网后重试');return r.json();}))).then(([geo,locations,tiles])=>{mapAssets={geo,locations,tiles};if(H.page()==='map')H.render();}).catch(e=>{mapLoading=null;H.toast(e.message);});}
function points(cell){return cell.polygon.map(p=>p.join(',')).join(' ');}
function mapToolIcon(kind){const paths={undo:'M10 5 4 11l6 6M4 11h15q9 0 9 9t-9 8h-6',minus:'M6 16h20',plus:'M6 16h20M16 6v20',fit:'M11 5H7q-2 0-2 2v4M21 5h4q2 0 2 2v4M5 21v4q0 2 2 2h4M27 21v4q0 2-2 2h-4M12 16h8M16 12v8',compass:'M16 4a12 12 0 1 0 0 24 12 12 0 0 0 0-24m5.5 6.5L18 18l-7.5 3.5L14 14Z'};return `<svg viewBox="0 0 32 32" aria-hidden="true"><path d="${paths[kind]}"/></svg>`;}
function mapTool(action,kind,label,data=''){return button(action,mapToolIcon(kind),`${data} aria-label="${label}" title="${label}"`,'camp-map-tool');}
function mapPage(){loadMap();if(!mapAssets)return '<div class="panel"><h2>地图</h2><p>正在准备地图…</p></div>';const {geo}=mapAssets,record=mapRecord(),all=record.showAll,area=geo.areas.find(a=>a.id==='basin');const minX=Math.min(...geo.areas.map(a=>a.x)),minY=Math.min(...geo.areas.map(a=>a.y)),maxX=Math.max(...geo.areas.map(a=>a.x+1)),maxY=Math.max(...geo.areas.map(a=>a.y+1));
 const fitted=all?[minX-.05,minY-.05,maxX-minX+.1,maxY-minY+.1]:[area.x-.07,area.y-.10,1.14,1.18];const bounds=mapView?.all===all?mapView.box:fitted;mapView={box:bounds,all};
 const outline=geo.outline.map(p=>[area.x+(area.mirror?1-p[0]:p[0]),area.y+p[1]].join(',')).join(' ');
 return `<section class="camp-map"><svg id="camp-map-svg" viewBox="${bounds.join(' ')}" role="img" aria-label="世界地图，可拖动缩放和选择地点"><defs><clipPath id="camp-basin"><polygon points="${outline}"></polygon></clipPath></defs>${geo.areas.filter(a=>all||a.id==='basin').map(a=>`<image class="camp-board-shadow" href="maps/shadow-${a.id}-${all?'joined':'solo'}.png" x="${a.x-.0625}" y="${a.y-.0625}" width="1.125" height="1.125"></image>`).join('')}<g ${all?'':'clip-path="url(#camp-basin)"'}><image href="maps/world.png" x="${minX}" y="${minY}" width="${maxX-minX}" height="${maxY-minY}" preserveAspectRatio="none"></image></g><g id="camp-map-tiles">${geo.cells.filter(c=>(all||c.area==='basin')&&record.explored.includes(c.id)).map(c=>tileImage(c)).join('')}</g><g>${geo.cells.filter(c=>all||c.area==='basin').map(c=>`<polygon class="camp-hex ${c.id===record.party?'party':''} ${c.id===record.selected?'selected':''}" points="${points(c)}" data-camp="mapSelect" data-id="${c.id}"></polygon>`).join('')}</g><image id="camp-party-marker" href="maps/party.png" width=".05" height=".069"></image></svg><div class="camp-map-top">${button('mapMenu','地图设置','','small')}${button('mapProgress','团队进度','','small')}</div><section class="camp-map-dock"><div id="camp-map-info"></div><div class="camp-map-controls-row"><div id="camp-map-tokens"></div><div class="camp-map-tools">${mapTool('mapUndo','undo','撤回上一步')}${mapTool('mapZoom','minus','缩小地图','data-factor="1.4"')}${mapTool('mapZoom','plus','放大地图','data-factor=".7142857"')}${mapTool('mapFit','fit','适合屏幕')}${mapTool('mapParty','compass','团队位置')}</div></div></section></section>`;
}
const tokenLabels=['导航','士气','饥饿'],tokenCrops=[[40,24,463,468],[531,24,472,469],[1028,24,468,469],[38,510,466,467],[531,509,472,468],[1027,509,469,470]];
function refreshMap(){const r=mapRecord(),options=M.mapOptions(r),cell=mapAssets.geo.cells.find(c=>c.id===r.selected),known=r.explored.includes(r.selected),location=mapAssets.locations.find(l=>l.id===r.selected),info=document.getElementById('camp-map-info');if(!info)return;
 const traveling=!!options.travelTo,blocked=r.party&&r.party!==r.selected?M.mapTravelBlockReason(r,r.selected,mapAssets.geo,mapAssets.locations):null;
 const action=!r.party?'放置团队 / 载入进度':options.explorationMode==='free'?'自由探索 · 到达此格':traveling?'确认抵达 · '+options.travelTo:r.party===r.selected?'旅行流程':blocked?'无法前往 · 查看原因':'开始旅行 · '+r.selected;
 info.innerHTML=`<small>${traveling?'旅行中 · '+esc(r.party)+' → '+esc(options.travelTo):r.party?'团队位于 '+esc(r.party):'按实体战役进度开始'}</small><h2>${esc(r.selected||'选择地点')} · ${esc(known?location?.name||'地点':'未探索')}</h2><p class="muted">${traveling?'请结算实体旅行卡后确认抵达':options.explorationMode==='free'?'自由探索已开启，点击地点会立即翻开。':r.party?'按实体游戏的结果记录位置与探索状态。':'先放置团队或载入实体探索进度。'}</p><div class="camp-summary"><div class="camp-map-local">${button('mapDetails','详情')}${button('mapNote','地点备注')}</div><div class="camp-map-travel">${traveling?button('mapCancelTravel','取消'):''}${button('mapArrive',esc(action),'','primary')}</div></div>`;
 document.querySelectorAll('.camp-hex').forEach(el=>{el.classList.toggle('party',el.dataset.id===r.party);el.classList.toggle('selected',el.dataset.id===r.selected);});
 document.querySelector('[data-camp="mapUndo"]').disabled=!r.undoHistory?.length;
 const party=mapAssets.geo.cells.find(c=>c.id===r.party),destination=mapAssets.geo.cells.find(c=>c.id===options.travelTo),marker=document.getElementById('camp-party-marker');if(marker){marker.style.display=party?'':'none';if(party){marker.setAttribute('x',(destination?(party.x+destination.x)/2:party.x)-.038);marker.setAttribute('y',(destination?(party.y+destination.y)/2:party.y)-.028);}}
 const tokens=document.getElementById('camp-map-tokens');tokens.hidden=!options.travelTokensEnabled;tokens.innerHTML=options.travelTokens.map((ready,index)=>button('mapToken',`<svg class="camp-token-art" viewBox="${tokenCrops[index+(ready?0:3)].join(' ')}" aria-hidden="true"><image href="maps/travel-tokens.png" width="1536" height="1024"/></svg><span>${tokenLabels[index]}</span>`,`data-index="${index}" aria-pressed="${ready}" aria-label="${tokenLabels[index]}：${ready?'可用':'已耗尽'}，点击翻转"`,'camp-travel-token')).join('');
 if(cell&&mapView?.all===false&&cell.area!=='basin'){H.mutate(s=>mapRecord(true).selected='E2',false);refreshMap();}
}
function refreshRevealedMap(){const r=mapRecord();document.getElementById('camp-map-tiles').innerHTML=mapAssets.geo.cells.filter(c=>(r.showAll||c.area==='basin')&&r.explored.includes(c.id)).map(tileImage).join('');refreshMap();}
function mapMenu(){const r=mapRecord(),o=M.mapOptions(r);H.modal('campaignMapMenu','地图设置',`<fieldset class="camp-map-modes"><legend>探索模式</legend><label><input type="radio" name="camp-map-mode" value="guided" ${o.explorationMode==='guided'?'checked':''}><span><b>提示探索（推荐）</b><small>检查出口和旅行标记；开始旅行后抽实体旅行卡，结算后再确认抵达。</small></span></label><label><input type="radio" name="camp-map-mode" value="free" ${o.explorationMode==='free'?'checked':''}><span><b>自由探索</b><small>点到任意地点就会翻开并更新团队位置，容易误触剧透。</small></span></label></fieldset><label class="camp-map-setting"><span><b>旅行标记</b><small>记录导航、士气、饥饿的状态；关闭后请自行核对实体标记。</small></span><input id="camp-map-travel-tokens" type="checkbox" ${o.travelTokensEnabled?'checked':''}></label><label class="camp-map-setting"><span><b>显示其他地图</b><small>显示环地与高地；未收到实体提示时请勿开启。</small></span><input id="camp-map-all" type="checkbox" ${r.showAll?'checked':''}></label>${button('mapProgress','团队位置与探索进度','','wide')}${button('mapRoom','与 APP 联机','','wide')}`,button('saveMapMenu','保存设置','','primary'));}
let pendingMapSettings;
function saveMapMenu(){const settings={explorationMode:document.querySelector('input[name="camp-map-mode"]:checked').value,travelTokensEnabled:document.getElementById('camp-map-travel-tokens').checked,showAll:document.getElementById('camp-map-all').checked};if(settings.explorationMode==='free'&&M.mapOptions(mapRecord()).explorationMode!=='free'){pendingMapSettings=settings;return H.modal('campaignMapFreeWarning','开启自由探索？','<p>开启后，点到任何六角地点都会立即翻开，并更新团队位置，不再检查路线或旅行标记。正常战役推荐使用“提示探索”。</p><p>如果正在旅行，切换后将取消尚未完成的旅行。</p>',button('mapMenu','返回设置')+button('confirmMapFree','仍要开启','','primary'));}applyMapSettings(settings);}
function mapRoom(){H.modal('campaignMapRoom','同一 Wi-Fi 联机','<p>请让房主在 APP 的地图设置中进入“地图联机”，创建房间，然后复制“浏览器加入地址”。</p><label for="camp-lan-address">浏览器加入地址</label><input id="camp-lan-address" type="url" inputmode="url" autocomplete="off" placeholder="http://192.168.1.8:12345/"><p>与房主连接同一 Wi-Fi，打开加入页面后输入六位房间码。无需外网服务器；房主请保持 APP 打开。</p><p>联机页面单独打开，保留这里的角色与背包记录。团队移动由 APP 房主控制，队友可以标点、画线与编辑备注。</p>',button('openMapRoom','打开加入页面','','primary'));}
function applyMapSettings(settings){if(H.mutate(s=>M.mapSettings(mapRecord(true),settings),false)){pendingMapSettings=null;H.close();H.render();H.toast('地图设置已保存');}}
function mapProgress(){const r=mapRecord(),current=r.party||'E2',known=new Set([...r.explored,current]);H.modal('campaignMapProgress','团队位置与探索进度',`<p>按实体战役的当前进度记录，只勾选已经探索的地点。保存后保留所有地点备注，可用地图撤回恢复上一步。</p><label for="camp-map-party">团队当前地点</label><select id="camp-map-party">${mapAssets.geo.cells.map(c=>`<option value="${c.id}" ${c.id===current?'selected':''}>${c.id}</option>`).join('')}</select>${mapAssets.geo.areas.map(area=>`<details class="camp-progress-area" ${area.id==='basin'||mapAssets.geo.cells.find(c=>c.id===current)?.area===area.id?'open':''}><summary>${esc(area.title)} · 已探索地点</summary><div class="camp-progress-grid">${mapAssets.geo.cells.filter(c=>c.area===area.id).map(c=>`<label><input type="checkbox" data-map-explored="${c.id}" ${known.has(c.id)?'checked':''} ${c.id===current?'disabled':''}>${c.id}</label>`).join('')}</div></details>`).join('')}${button('mapStart','按起始事件放置在 E2','','wide')}`,button('saveMapProgress','保存已有进度','','primary'));}
function saveMapProgress(){const party=document.getElementById('camp-map-party').value,explored=[...document.querySelectorAll('[data-map-explored]:checked')].map(c=>c.dataset.mapExplored);if(H.mutate(s=>M.mapRestoreProgress(mapRecord(true),party,explored,mapAssets.geo),false)){H.close();mapView=null;H.render();H.toast('团队位置与探索进度已保存');}}
function mapAction(){const r=mapRecord(),o=M.mapOptions(r);if(!r.party)return mapProgress();if(r.party===r.selected&&!o.travelTo&&o.explorationMode==='guided')return H.modal('campaignTravelGuide','旅行流程','<p>先选择相邻且出口相通的地点，再按“开始旅行”。按实体规则抽取和结算旅行卡后，按“确认抵达”。导航、士气和饥饿标记请按实体结算结果翻转。</p>');if(H.mutate(s=>{const map=mapRecord(true);if(o.explorationMode==='free')M.mapArrive(map,map.selected);else if(o.travelTo)M.mapCompleteTravel(map);else M.mapBeginTravel(map,map.selected,mapAssets.geo,mapAssets.locations);},false))refreshRevealedMap();}

function tileImage(cell){const r=mapAssets.tiles[cell.id];return r?`<image data-tile="${cell.id}" href="maps/${cell.id}.png" x="${r[0]}" y="${r[1]}" width="${r[2]}" height="${r[3]}" preserveAspectRatio="none"></image>`:'';}
function bindMap(){const svg=document.getElementById('camp-map-svg');if(!svg)return;refreshMap();let down,pointsDown=new Map(),pinch;
 const setBox=box=>{mapView.box=box;svg.setAttribute('viewBox',box.join(' '));};
 svg.addEventListener('pointerdown',e=>{pointsDown.set(e.pointerId,[e.clientX,e.clientY]);if(pointsDown.size===1)down={x:e.clientX,y:e.clientY,box:[...mapView.box]};if(pointsDown.size===2){const p=[...pointsDown.values()];pinch={distance:Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]),box:[...mapView.box]};}});
 svg.addEventListener('pointermove',e=>{if(!pointsDown.has(e.pointerId))return;pointsDown.set(e.pointerId,[e.clientX,e.clientY]);if(pointsDown.size===2&&pinch){const p=[...pointsDown.values()],distance=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]),factor=pinch.distance/Math.max(distance,10),b=pinch.box;if(b[2]*factor>.15&&b[2]*factor<6)setBox([b[0]+b[2]*(1-factor)/2,b[1]+b[3]*(1-factor)/2,b[2]*factor,b[3]*factor]);lastDrag=Date.now();}else if(down){const rect=svg.getBoundingClientRect(),dx=e.clientX-down.x,dy=e.clientY-down.y;if(Math.hypot(dx,dy)>6){if(!svg.hasPointerCapture(e.pointerId))svg.setPointerCapture(e.pointerId);const factor=Math.max(down.box[2]/rect.width,down.box[3]/rect.height);setBox([down.box[0]-dx*factor,down.box[1]-dy*factor,down.box[2],down.box[3]]);lastDrag=Date.now();}}});
 const end=e=>{pointsDown.delete(e.pointerId);if(pointsDown.size<2)pinch=null;if(!pointsDown.size)down=null;};svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);
 svg.addEventListener('wheel',e=>{e.preventDefault();zoomMap(e.deltaY>0?1.15:.87);},{passive:false});
}
function zoomMap(factor){if(!mapView)return;const b=mapView.box;if(b[2]*factor<.15||b[2]*factor>6)return;mapView.box=[b[0]+b[2]*(1-factor)/2,b[1]+b[3]*(1-factor)/2,b[2]*factor,b[3]*factor];document.getElementById('camp-map-svg')?.setAttribute('viewBox',mapView.box.join(' '));}
function mapDetails(){const r=mapRecord(),loc=mapAssets.locations.find(x=>x.id===r.selected);if(!r.explored.includes(r.selected))return H.modal('campaignMapDetails','未探索地点','<p>地点名称、地形和指引保持隐藏。</p>'+button('mapNote','地点备注'));
 H.modal('campaignMapDetails',esc(r.selected+' · '+loc.name),`<img class="camp-map-detail" src="maps/${r.selected}.png" alt="${esc(loc.name)}完整地点板块">${(loc.references||[]).map(id=>button('reference',esc(root.Core.display(id)),`data-reference="${esc(id)}"`)).join('')}<p>与地点指引互动时，请按实体规则执行。</p>${button('mapNote','地点备注')}`);}
function showMapNote(){const r=mapRecord();H.modal('campaignMapNote',esc(r.selected+' · 地点备注'),`<textarea id="camp-map-note" rows="7" maxlength="6000" placeholder="记录线索、已完成事件和待办事项…">${esc(r.notes[r.selected]||'')}</textarea>`,button('saveMapNote','保存备注','','primary'));}
const spoilerText='首次游玩不建议使用软件内的地图功能。APP 包含地图、卡牌和剧情等剧透内容，更适合已经游玩过一段时间，或进行二周目的玩家。如果不想提前知道剧情和未探索内容，请先不要使用地图，也不要提前展开卡牌正文。';
let mapWarned=false;
function mapWarning(){if(mapWarned||localStorage.getItem('arydia-map-warning-skip')==='yes')return;mapWarned=true;H.modal('campaignMapWarning','初见不建议使用此地图功能',`<p>${spoilerText}</p><label><input type="checkbox" id="camp-map-skip">下次不再提醒</label>`,button('acceptMapWarning','我已了解','','primary'));}
function searchPrefs(){H.modal('campaignSearchPrefs','防剧透设置',`<label><input type="checkbox" id="camp-show-titles" ${state().prefs.databaseTitles?'checked':''}>显示卡牌标题与字母状态</label><label><input type="checkbox" id="camp-show-text" ${state().prefs.databaseText?'checked':''}>默认展开卡牌正文（涉及剧透）</label>`,button('saveSearchPrefs','保存','','primary'));}
function iconLegend(){const keys=['hp','mp','sp','rp','xp','combo','threat','kae','defense','durability','marker','damage','bonus_damage','piercing_damage','distance','flip','move','success','failure','hex_success','hex_failure','event','return','discard','archive','melee','ranged','area','rest','insight'];H.modal('campaignLegend','游戏图标说明',['hp',...keys.filter(k=>k!=='hp'),'hit_point','armored_point','weak_point','critical'].map(key=>`<div class="camp-legend-row">${assets.icons[key]?`<img src="${esc(assets.icons[key])}" alt="">`:''}<b>${esc(assets.names[key]||({hit_point:'生命点',armored_point:'护甲点',weak_point:'弱点',critical:'暴击'})[key]||key)}</b></div>`).join(''));}
function updates(startup=false){H.modal(startup?'welcomeCampaignUpdate':'campaignUpdate','更新公告',`<h3>本次更新</h3><p>• 已加入完整中文卡牌文本。<br>• 团队背包与个人背包可分别记录持有卡牌和关键词。<br>• 新增垂钓日志，记录鱼类与垂钓板块。<br>• 加入地图功能，可查看地点、记录备注并辅助旅行。</p><h3>卡牌文本说明</h3><p>卡牌文本经过手工初步校对，仍可能有错字、漏字或内容不准确的地方，请以实体卡牌和说明书为准。发现问题可以在交流群反馈，后续会继续修正。</p><h3>剧透提醒</h3><p>${spoilerText}</p><h3>免费使用，自愿支持</h3><p>本软件由个人开发和维护，所有功能完全免费。整理资料、校对和维护需要投入时间，如果软件对你有帮助，欢迎自愿打赏支持。是否赞助都不影响正常使用。</p>${H.supportButtons()}<h3>软件更新</h3><p>目前请通过 QQ 交流群的群文件下载更新。后续如果收到的赞助足以承担服务器的运行和维护费用，就会加入在线更新功能。软件始终免费，是否赞助都不影响正常使用。</p><p>交流群：328669965</p>`,button('acceptUpdates',startup?'开始使用':'关闭',`data-startup="${startup}"`,'primary'));localStorage.setItem('arydia-web-update-seen','3.9.0');}
function startNotices(){if(localStorage.getItem('arydia-web-free-skip')==='yes')return nextNotice();H.modal('welcomeCampaignFree','免费与防骗提醒','<h2>完全免费，请勿购买</h2><p>本软件由 IzumiSaito 个人开发，下载、使用及全部功能均不收取费用，请勿通过付费渠道购买。任何售卖本软件、收费解锁功能等行为均与作者无关，请提高警惕，谨防受骗。</p><p>软件内赞助仅为自愿支持，不影响正常使用。</p><label><input type="checkbox" id="camp-free-skip">下次不再提醒</label>',button('acceptFree','我已知晓','','primary'));}
function nextNotice(){if(localStorage.getItem('arydia-web-update-seen')!=='3.9.0')updates(true);else if(root.Intro&&!Intro.accepted())Intro.show();}
function mount(page){if(page==='map'){bindMap();if(mapAssets)mapWarning();}if(page==='characters'&&H.active()){const footer=document.querySelector('.growth-footer');if(footer&&!footer.querySelector('[data-camp="personal"]'))footer.innerHTML=button('personal','个人背包','','small');}bindLocalTabs();}
function bindLocalTabs(){const target=document.querySelector('.camp-search,.camp-inventory');if(!target)return;let down;target.addEventListener('touchstart',e=>{if(e.target.closest('input,textarea,select'))return;down=[e.touches[0].clientX,e.touches[0].clientY];},{passive:true});target.addEventListener('touchend',e=>{if(!down)return;const dx=e.changedTouches[0].clientX-down[0],dy=e.changedTouches[0].clientY-down[1];down=null;if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.6)return;if(H.page()==='search')searchMode=1-searchMode;else bagTab=M.bag(state(),owner())&&Math.max(0,Math.min(owner()?1:2,bagTab+(dx<0?1:-1)));H.render();},{passive:true});}
document.addEventListener('input',e=>{if(!H)return;if(e.target.id==='camp-card-memo'){cardView.memoDraft=e.target.value;}else if(e.target.id==='camp-bag-query'){bagQuery=e.target.value;document.getElementById('camp-bag-items').innerHTML=inventoryItems();}else if(e.target.id==='camp-search-query'){searchTerms[searchMode]=e.target.value;document.getElementById('camp-search-results').innerHTML=searchResults();}else if(e.target.id==='camp-add-input')previewAdd();else if(e.target.id==='camp-fish-notes')H.mutate(s=>M.fishing(s,true).notes=e.target.value,false);});
document.addEventListener('change',e=>{if(e.target.dataset.fish){const old=e.target.checked;if(!H.mutate(s=>M.fishMark(s,e.target.dataset.fish,Number(e.target.value),old),false))e.target.checked=!old;refreshFish();}});
let addIdle;
document.addEventListener('scroll',()=>{if(!H||!['inventory','personalInventory'].includes(H.page()))return;const dock=document.querySelector('.camp-add-dock');if(!dock)return;clearTimeout(addIdle);dock.classList.add('is-scrolling');addIdle=setTimeout(()=>dock.classList.remove('is-scrolling'),300);},{passive:true,capture:true});
let holdTimer,holdStart,suppressClickUntil=0;
document.addEventListener('pointerdown',e=>{const row=e.target.closest('[data-manage]');if(!row)return;holdStart=[e.clientX,e.clientY];clearTimeout(holdTimer);holdTimer=setTimeout(()=>{suppressClickUntil=Date.now()+600;manage(row.dataset.manage);},550);},{passive:true});
document.addEventListener('pointermove',e=>{if(holdStart&&Math.hypot(e.clientX-holdStart[0],e.clientY-holdStart[1])>8)clearTimeout(holdTimer);},{passive:true});
for(const event of ['pointerup','pointercancel'])document.addEventListener(event,()=>{clearTimeout(holdTimer);holdStart=null;},{passive:true});
document.addEventListener('contextmenu',e=>{const row=e.target.closest('[data-manage]');if(row){e.preventDefault();clearTimeout(holdTimer);manage(row.dataset.manage);}});
document.addEventListener('keydown',e=>{const row=e.target.closest('[data-manage]');if(row&&((e.shiftKey&&e.key==='F10')||e.key==='ContextMenu')){e.preventDefault();manage(row.dataset.manage);}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-camp]');if(!b||!H)return;e.preventDefault();e.stopImmediatePropagation();if(Date.now()<suppressClickUntil)return;const action=b.dataset.camp;try{
 if(action==='go'){bagQuery='';bagTab=0;H.go(b.dataset.page);}
 else if(action==='personal'){bagQuery='';bagTab=0;H.go('personalInventory');}
 else if(action==='tab'){const i=Number(b.dataset.index);if(b.dataset.kind==='bag'){bagTab=i;H.render();}else if(b.dataset.kind==='search'){searchMode=i;H.render();}else if(b.dataset.kind==='face'){cardView.face=i;paintCard();}else if(b.dataset.kind==='add'){addView.mode=i;paintAdd();}}
 else if(action==='add')showAdd();else if(action==='saveBag')saveBag();else if(action==='chooseAdd'){addView.choices[b.dataset.raw]=b.dataset.key;previewAdd();}
 else if(action==='owned'){const entry=M.held(state(),owner()).find(x=>x.id===b.dataset.id);if(entry)showCard(cardOf(entry),true,entry.id,owner());}
 else if(action==='saveCardMemo'){const note=document.getElementById('camp-card-memo').value;if(H.mutate(s=>M.setNote(s,cardView.entryId,note,cardView.ownerId),false)){cardView.memoDraft=note;document.getElementById('camp-memo-status').textContent='已保存';}}
 else if(action==='sourceSearch'){searchMode=0;searchTerms[0]=cardView.card.references.find(r=>cardView.card.state&&r.endsWith(cardView.card.state))||cardView.card.references[0]||cardView.card.number;H.close();H.go('search');}
 else if(action==='sources'){const list=M.held(state(),owner()).filter(x=>M.keywords(x).includes(b.dataset.key));H.modal('campaignSources',esc(b.dataset.key),list.map(x=>button('owned',esc(x.display+' · '+x.title),`data-id="${esc(x.id)}"`)).join(''));}
 else if(action==='card'||action==='cardVariant')showCard(byKey(b.dataset.key),action==='cardVariant'&&cardView.owned,action==='cardVariant'?cardView.entryId:null,action==='cardVariant'?cardView.ownerId:null);
 else if(action==='reference'){const list=byReference(b.dataset.reference);if(list.length===1||!state().prefs.databaseTitles)showCard(list[0]);else H.modal('campaignChoices','选择卡牌',list.map(c=>button('card',esc(c.display),`data-key="${esc(c.key)}"`)).join(''));}
 else if(action==='revealCard'){cardView.revealed.add(cardView.face);cardView.named=true;paintCard();}else if(action==='cardTitle'){cardView.named=true;paintCard();}
 else if(action==='manage')manage(b.dataset.id);else if(action==='history')history();
 else if(action==='archive'){if(H.mutate(s=>M.archive(s,b.dataset.id,owner()),false)){H.close();H.render();}}
 else if(action==='restore'){const entry=M.bag(state(),owner()).cards.find(x=>x.id===b.dataset.id);if(H.mutate(s=>M.add(s,cardOf(entry),assets.meta,owner(),entry.squillNumber),false)){H.close();H.render();}}
 else if(action==='saveEntry'){const values={keywords:document.getElementById('camp-edit-words').value.split('\n'),note:document.getElementById('camp-edit-note').value,marks:Number(document.getElementById('camp-edit-marks').value)};if(H.mutate(s=>M.update(s,b.dataset.id,values,owner()),false)){H.close();H.render();}}
 else if(action==='coin')H.modal('campaignCoin','梓昆币 #'+b.dataset.key,'<p>编号用于识别，每张计作一枚。移出后可按编号重新添加。</p>',button('removeCoin','移出记录',`data-number="${b.dataset.key}"`));else if(action==='removeCoin'){if(H.mutate(s=>M.removeCoin(s,Number(b.dataset.number),owner()),false)){H.close();H.render();}}
 else if(action==='fishing')fishing();else if(action==='searchPrefs')searchPrefs();else if(action==='saveSearchPrefs'){H.mutate(s=>{s.prefs.databaseTitles=document.getElementById('camp-show-titles').checked;s.prefs.databaseText=document.getElementById('camp-show-text').checked;},false);H.close();H.render();}
 else if(action==='clearHistory'){localStorage.removeItem('arydia-web-recent-cards');searchTerms=['',''];H.mutate(s=>s.recent=[]);}
 else if(action==='icons')iconLegend();else if(action==='updates')updates();
 else if(action==='acceptFree'){if(document.getElementById('camp-free-skip').checked)localStorage.setItem('arydia-web-free-skip','yes');H.close();nextNotice();}
 else if(action==='acceptUpdates'){localStorage.setItem('arydia-web-update-seen','3.9.0');H.close();if(b.dataset.startup==='true'&&root.Intro&&!Intro.accepted())Intro.show();}
 else if(action==='retry'){loading=null;error='';load();}
 else if(action==='mapSelect'){if(Date.now()-lastDrag<160)return;if(H.mutate(s=>{const r=mapRecord(true);if(M.mapOptions(r).explorationMode==='free')M.mapArrive(r,b.dataset.id);else r.selected=b.dataset.id;},false))refreshRevealedMap();}
 else if(action==='mapArrive')mapAction();
 else if(action==='mapUndo'){if(H.mutate(s=>M.mapUndo(mapRecord(true)),false)){if(mapRecord().showAll!==mapView.all)H.render();else refreshRevealedMap();H.toast('已撤回上一步');}}
 else if(action==='mapCancelTravel'){if(H.mutate(s=>M.mapCancelTravel(mapRecord(true)),false))refreshMap();}
 else if(action==='mapToken'){const index=Number(b.dataset.index);if(H.mutate(s=>M.mapSetToken(mapRecord(true),index,!M.mapOptions(mapRecord()).travelTokens[index]),false))refreshMap();}
 else if(action==='mapZoom')zoomMap(Number(b.dataset.factor));else if(action==='mapFit'){mapView=null;H.render();}else if(action==='mapParty'){const c=mapAssets.geo.cells.find(x=>x.id===mapRecord().party);if(c){const box=mapView.box;mapView.box=[c.x-box[2]/2,c.y-box[3]/2,box[2],box[3]];document.getElementById('camp-map-svg').setAttribute('viewBox',mapView.box.join(' '));}}
 else if(action==='mapDetails')mapDetails();else if(action==='mapNote')showMapNote();else if(action==='saveMapNote'){H.mutate(s=>mapRecord(true).notes[mapRecord().selected]=document.getElementById('camp-map-note').value,false);H.close();}
 else if(action==='mapMenu')mapMenu();else if(action==='saveMapMenu')saveMapMenu();else if(action==='confirmMapFree'){if(pendingMapSettings)applyMapSettings(pendingMapSettings);}
 else if(action==='mapRoom')mapRoom();else if(action==='openMapRoom'){const url=M.lanMapUrl(document.getElementById('camp-lan-address').value);window.open(url,'_blank','noopener,noreferrer');}
 else if(action==='mapProgress')mapProgress();else if(action==='saveMapProgress')saveMapProgress();
 else if(action==='mapStart'){if(H.mutate(s=>M.mapRestoreProgress(mapRecord(true),'E2',['E2'],mapAssets.geo),false)){H.close();mapView=null;H.render();}}
 else if(action==='acceptMapWarning'){if(document.getElementById('camp-map-skip').checked)localStorage.setItem('arydia-map-warning-skip','yes');H.close();}
 }catch(err){H.toast(err.message);}
},true);
document.addEventListener('change',event=>{if(event.target.id!=='camp-map-party')return;document.querySelectorAll('[data-map-explored]').forEach(box=>{box.disabled=box.dataset.mapExplored===event.target.value;if(box.disabled)box.checked=true;});});
root.Campaign={connect(host){H=host;load();},view:shell,mount,startNotices,updates,iconLegend};
})(window);
